          <div className="bg-slate-800/50 rounded-2xl p-6 border border-slate-700/50">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 block">Następny przegląd</label>
            <input 
              type="month"
              value={data.nextInspectionDate}
              onChange={(e) => updateField('nextInspectionDate', e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-6 py-4 text-xl font-black text-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all uppercase"
