};

import React, { useState } from 'react';
import { PlateData } from '../types';
import { X, Save } from 'lucide-react';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onApply: (updates: Partial<PlateData>) => void;
  currentTemplate: PlateData;
}

export const GlobalEditorModal: React.FC<Props> = ({ isOpen, onClose, onApply, currentTemplate }) => {
  const [updates, setUpdates] = useState<Partial<PlateData>>({
    customerName: currentTemplate.customerName,
    installationYear: currentTemplate.installationYear,
    projectNumber: currentTemplate.projectNumber,
    sapNumberSuffix: currentTemplate.sapNumberSuffix,
    nextInspectionDate: currentTemplate.nextInspectionDate
  });

  if (!isOpen) return null;

  const handleChange = (field: keyof PlateData, value: any) => {
    setUpdates(prev => ({ ...prev, [field]: value }));
  };

  const handleApply = () => {
    onApply(updates);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <h3 className="font-bold flex items-center gap-2">
            <Save size={20} /> Edycja Masowa Projektów
          </h3>
          <button onClick={onClose} className="hover:bg-slate-700 p-1 rounded-full transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-4">
          <p className="text-sm text-gray-500 mb-4">
            Wprowadzone tutaj dane zostaną zastosowane do <b>wszystkich</b> aktualnie utworzonych tabliczek.
          </p>

          <div className="grid grid-cols-1 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nazwa Klienta</label>
              <input 
                type="text"
                value={updates.customerName}
                onChange={(e) => handleChange('customerName', e.target.value)}
                className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Rok Instalacji</label>
                <input 
                  type="number"
                  value={updates.installationYear}
                  onChange={(e) => handleChange('installationYear', parseInt(e.target.value))}
                  className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Numer Projektu</label>
                <input 
                  type="number"
                  value={updates.projectNumber}
                  onChange={(e) => handleChange('projectNumber', parseInt(e.target.value))}
                  className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Numer SAP</label>
              <div className="relative group flex items-center">
                <span className="absolute left-3 text-sm font-mono text-slate-400 select-none pointer-events-none font-bold">46120</span>
                <input 
                  type="text"
                  maxLength={5}
                  value={updates.sapNumberSuffix}
                  onChange={(e) => handleChange('sapNumberSuffix', e.target.value)}
                  className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 outline-none font-mono tracking-widest font-bold text-right pr-3"
                  placeholder="XXXXX"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Data kolejnego przeglądu</label>
              <input 
                type="month"
                value={updates.nextInspectionDate}
                onChange={(e) => handleChange('nextInspectionDate', e.target.value)}
                className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
          </div>
        </div>

        <div className="p-4 bg-gray-50 flex gap-3 justify-end">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-gray-600 font-semibold hover:bg-gray-200 rounded-lg transition-colors"
          >
            Anuluj
          </button>
          <button 
            onClick={handleApply}
            className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 transition-colors shadow-lg"
          >
            Zastosuj do wszystkich
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { PlateData, BeamConfig, LevelConfig, BEAM_PROFILES } from '../types';
import { Plus, Trash2, RotateCcw, X, ClipboardList, Ruler, Box, HardHat, Info, Hash } from 'lucide-react';
import { calculateMaxBayLoad } from '../utils';

interface Props {
  data: PlateData;
  onChange: (data: PlateData) => void;
  onDuplicate: () => void;
  onRemove: () => void;
}

export const PlateEditor: React.FC<Props> = ({ data, onChange, onDuplicate, onRemove }) => {

  const updateField = <K extends keyof PlateData>(field: K, value: PlateData[K]) => {
    onChange({ ...data, [field]: value });
  };

  const addLevel = () => {
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      label: `A${data.subsequentLevels.length + 1}`,
      height: 1250
    };
    updateField('subsequentLevels', [...data.subsequentLevels, newLevel]);
  };

  const removeLevel = (id: string) => {
    updateField('subsequentLevels', data.subsequentLevels.filter(l => l.id !== id));
  };

  const updateLevel = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = data.subsequentLevels.map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels', updated);
  };

  const addLevel2 = () => {
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      label: `B${(data.subsequentLevels2?.length || 0) + 1}`,
      height: 1250
    };
    updateField('subsequentLevels2', [...(data.subsequentLevels2 || []), newLevel]);
  };

  const removeLevel2 = (id: string) => {
    updateField('subsequentLevels2', (data.subsequentLevels2 || []).filter(l => l.id !== id));
  };

  const updateLevel2 = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = (data.subsequentLevels2 || []).map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels2', updated);
  };

  const addBeam = () => {
    const newBeam: BeamConfig = {
      id: Math.random().toString(36).substr(2, 9),
      levelLabel: 'A',
      length: 2700,
      profileType: "E0485/15",
      profileWidth: 125,
      loadCount: 3,
      loadWeight: 400
    };
    updateField('beams', [...data.beams, newBeam]);
  };

  const removeBeam = (id: string) => {
    updateField('beams', data.beams.filter(b => b.id !== id));
  };

  const updateBeam = (id: string, field: keyof BeamConfig, value: string | number) => {
    let updatedBeams = data.beams.map(b => b.id === id ? { ...b, [field]: value } : b);

    if (field === 'profileType') {
      const selectedProfile = BEAM_PROFILES.find(p => p.type === value);
      if (selectedProfile) {
        updatedBeams = updatedBeams.map(b => b.id === id ? { ...b, profileWidth: selectedProfile.h } : b);
      }
    }

    updateField('beams', updatedBeams);
  };

  const calculatedBayLoad = calculateMaxBayLoad(data);

  return (
    <div className="space-y-8 pb-12">
      {/* Header Actions */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex justify-between items-center no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-blue-200 shadow-lg">
            <ClipboardList size={22} />
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-800">Parametry Tabliczki</h2>
            <p className="text-xs text-slate-500 font-medium">Edytujesz: <span className="text-blue-600">Project {data.projectNumber}</span></p>
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={onDuplicate} 
            className="flex items-center gap-1.5 text-xs font-bold bg-slate-100 text-slate-700 px-4 py-2 rounded-lg hover:bg-slate-200 transition-all border border-slate-200"
          >
            Duplikuj
          </button>
          <button 
            onClick={onRemove} 
            className="flex items-center gap-1.5 text-xs font-bold bg-red-50 text-red-600 px-4 py-2 rounded-lg hover:bg-red-100 transition-all border border-red-100"
          >
            <Trash2 size={14} /> Usuń
          </button>
        </div>
      </div>

      {/* Main Settings Section */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
        <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex items-center gap-2">
          <Hash size={18} className="text-slate-400" />
          <h3 className="text-sm font-bold text-slate-700 uppercase tracking-wider">Dane Podstawowe</h3>
        </div>
        <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2">
            <label className="label">Klient / Nazwa Instalacji</label>
            <input 
              type="text"
              value={data.customerName}
              onChange={(e) => updateField('customerName', e.target.value)}
              className="input-field w-full"
