            <div className="flex flex-1 items-center gap-2">
              <span className="font-mono text-sm font-bold text-slate-500 whitespace-nowrap">STD'B'</span>
              <div className="relative flex-1 max-w-[100px]">
                <input 
                  type="text" 
                  value={data.frameType}
                  onChange={(e) => updateField('frameType', e.target.value)}
                  className="input-field w-full text-center font-bold px-1"
                  placeholder="Typ"
                />
              </div>
              <span className="font-mono text-slate-300 text-lg">'</span>
              <div className="relative flex-1 max-w-[120px]">
                <input 
                  type="number" 
                  value={data.frameDepth}
                  onChange={(e) => updateField('frameDepth', parseInt(e.target.value))}
                  className="input-field w-full text-center pr-7 px-1"
                />
                <span className="absolute right-2 top-2.5 text-[8px] text-slate-400 font-black">mm</span>
              </div>
              <span className="font-mono text-slate-300 text-lg">'</span>
              <div className="relative flex-1 max-w-[140px]">
                <input 
                  type="number" 
                  value={data.frameHeight}
                  onChange={(e) => updateField('frameHeight', parseInt(e.target.value))}
                  className="input-field w-full text-center pr-7 px-1"
                />
                <span className="absolute right-2 top-2.5 text-[8px] text-slate-400 font-black">mm</span>
              </div>
            </div>
          </div>

          {data.frameType2 !== undefined && (
            <div className="flex items-center gap-4 bg-blue-50/30 p-3 rounded-xl border border-blue-100 animate-in slide-in-from-top-4">
              <div className="text-[11px] font-black text-blue-400 whitespace-nowrap uppercase min-w-[60px]">Rama 2</div>
              <div className="flex flex-1 items-center gap-2">
                <span className="font-mono text-sm font-bold text-slate-500 whitespace-nowrap">STD'B'</span>
                <div className="relative flex-1 max-w-[100px]">
                  <input 
                    type="text" 
                    value={data.frameType2 || ''}
                    onChange={(e) => updateField('frameType2', e.target.value)}
                    className="input-field w-full text-center font-bold px-1"
                  />
                </div>
                <span className="font-mono text-slate-300 text-lg">'</span>
                <div className="relative flex-1 max-w-[120px]">
                  <input 
                    type="number" 
                    value={data.frameDepth2 || 0}
                    onChange={(e) => updateField('frameDepth2', parseInt(e.target.value))}
                    className="input-field w-full text-center pr-7 px-1"
                  />
                  <span className="absolute right-2 top-2.5 text-[8px] text-slate-400 font-black">mm</span>
                </div>
                <span className="font-mono text-slate-300 text-lg">'</span>
                <div className="relative flex-1 max-w-[140px]">
                  <input 
                    type="number" 
                    value={data.frameHeight2 || 0}
                    onChange={(e) => updateField('frameHeight2', parseInt(e.target.value))}
                    className="input-field w-full text-center pr-7 px-1"
                  />
                  <span className="absolute right-2 top-2.5 text-[8px] text-slate-400 font-black">mm</span>
                </div>
              </div>
              <button onClick={() => onChange({ ...data, frameType2: undefined, frameDepth2: undefined, frameHeight2: undefined })} className="text-red-400 hover:text-red-600 p-1">
                <X size={16} />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Final Data Section - Light Theme */}
      <div className="bg-white rounded-2xl p-8 text-slate-800 border border-slate-200 shadow-sm no-print">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-emerald-500/20 shadow-lg">
            <Info size={22} />
          </div>
          <h3 className="text-lg font-bold">Dane Końcowe</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Ilość poziomów (do Qp)</label>
              <input 
                type="number"
                value={data.highestLevelIndex}
                onChange={(e) => updateField('highestLevelIndex', parseInt(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-slate-800 focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold font-mono"
              />
              <p className="text-[10px] text-slate-400 mt-2 italic">Podaj liczbę poziomów składowych (np. 4), aby poprawnie wyliczyć Qp.</p>
            </div>

            <div className="flex gap-4">
              <div className="flex-1 group">
                <div className="flex justify-between items-center mb-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Qp (Obciążenie Pola)</label>
                  <button onClick={() => updateField('maxBayLoadOverride', undefined)} className="text-slate-400 hover:text-emerald-500 transition-colors">
                    <RotateCcw size={12} />
                  </button>
                </div>
                <div className="relative">
                  <input 
                    type="number"
                    value={data.maxBayLoadOverride ?? calculatedBayLoad}
                    onChange={(e) => updateField('maxBayLoadOverride', parseInt(e.target.value))}
                    className={`w-full bg-slate-50 border ${data.maxBayLoadOverride ? 'border-amber-400' : 'border-slate-200'} rounded-xl px-4 py-3 text-lg font-black text-emerald-600 outline-none font-mono`}
                  />
                  <span className="absolute right-4 top-4 text-xs font-bold text-slate-400">kg</span>
                </div>
              </div>

              <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">H (Wysokość Regału)</label>
                  <button onClick={() => updateField('totalHeightOverride', undefined)} className="text-slate-400 hover:text-emerald-500 transition-colors">
                    <RotateCcw size={12} />
                  </button>
                </div>
                <div className="relative">
                  <input 
                    type="number"
                    value={data.totalHeightOverride || (data.frameHeight - 150)}
                    onChange={(e) => updateField('totalHeightOverride', parseInt(e.target.value))}
                    className={`w-full bg-slate-50 border ${data.totalHeightOverride ? 'border-amber-400' : 'border-slate-200'} rounded-xl px-4 py-3 text-lg font-black text-emerald-600 outline-none font-mono`}
                  />
                  <span className="absolute right-4 top-4 text-xs font-bold text-slate-400">mm</span>
                </div>
              </div>
            </div>
          </div>

          <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 block">Następny przegląd</label>
            <input 
              type="month"
              value={data.nextInspectionDate}
              onChange={(e) => updateField('nextInspectionDate', e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-xl px-6 py-4 text-xl font-black text-slate-800 focus:ring-2 focus:ring-emerald-500 outline-none transition-all uppercase font-mono"
            />
          </div>
        </div>
      </div>

      <datalist id="profile-list">
        {BEAM_PROFILES.map(p => (
          <option key={p.type} value={p.type}>{p.type} (H={p.h})</option>
        ))}
      </datalist>

      <style>{`
        .label {
          display: block;
          font-size: 0.65rem;
          font-weight: 800;
          color: #64748b;
          text-transform: uppercase;
          letter-spacing: 0.05em;
          margin-bottom: 0.5rem;
        }
        .input-field {
          display: block;
          border: 1px solid #e2e8f0;
          background: #ffffff;
          border-radius: 0.6rem;
          padding: 0.6rem 0.8rem;
          font-size: 0.9rem;
          color: #1e293b;
          font-weight: 500;
          outline: none;
          transition: all 0.2s;
          /* High-quality Coding Monospace Stack */
          font-family: "JetBrains Mono", "Fira Code", "Source Code Pro", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
        }
        .input-field:focus {
          border-color: #3b82f6;
          box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.1);
          background: #f8faff;
        }
        .input-field::placeholder {
          color: #cbd5e1;
        }
      `}</style>
    </div>
  );
};

import React from 'react';
import { PlateData, BeamConfig, LevelConfig, BEAM_PROFILES } from '../types';
import { Plus, Trash2, RotateCcw, X, ClipboardList, Ruler, Box, HardHat, Info, Hash } from 'lucide-react';
import { calculateMaxBayLoad } from '../utils';

interface Props {
  data: PlateData;
  onChange: (data: PlateData) => void;
  onDuplicate: () => void;
  onRemove: () => void;
}

export const PlateEditor: React.FC<Props> = ({ data, onChange, onDuplicate, onRemove }) => {

  const updateField = <K extends keyof PlateData>(field: K, value: PlateData[K]) => {
    onChange({ ...data, [field]: value });
  };

  const addLevel = () => {
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      label: `A${data.subsequentLevels.length + 1}`,
      height: 1250
    };
    updateField('subsequentLevels', [...data.subsequentLevels, newLevel]);
  };

  const removeLevel = (id: string) => {
    updateField('subsequentLevels', data.subsequentLevels.filter(l => l.id !== id));
  };

  const updateLevel = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = data.subsequentLevels.map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels', updated);
  };

  const addLevel2 = () => {
    const newLevel: LevelConfig = {
      id: Math.random().toString(36).substr(2, 9),
      label: `B${(data.subsequentLevels2?.length || 0) + 1}`,
      height: 1250
    };
    updateField('subsequentLevels2', [...(data.subsequentLevels2 || []), newLevel]);
  };

  const removeLevel2 = (id: string) => {
    updateField('subsequentLevels2', (data.subsequentLevels2 || []).filter(l => l.id !== id));
  };

  const updateLevel2 = (id: string, field: keyof LevelConfig, value: string | number) => {
    const updated = (data.subsequentLevels2 || []).map(l => l.id === id ? { ...l, [field]: value } : l);
    updateField('subsequentLevels2', updated);
  };

  const addBeam = () => {
    const newBeam: BeamConfig = {
      id: Math.random().toString(36).substr(2, 9),
      levelLabel: 'A',
      length: 2700,
      profileType: "E0485/15",
      profileWidth: 125,
      loadCount: 3,
      loadWeight: 400
    };
    updateField('beams', [...data.beams, newBeam]);
  };

  const removeBeam = (id: string) => {
    updateField('beams', data.beams.filter(b => b.id !== id));
  };

  const updateBeam = (id: string, field: keyof BeamConfig, value: string | number) => {
    let updatedBeams = data.beams.map(b => b.id === id ? { ...b, [field]: value } : b);

    if (field === 'profileType') {
      const selectedProfile = BEAM_PROFILES.find(p => p.type === value);
      if (selectedProfile) {
        updatedBeams = updatedBeams.map(b => b.id === id ? { ...b, profileWidth: selectedProfile.h } : b);
      }
    }

    updateField('beams', updatedBeams);
  };

  const calculatedBayLoad = calculateMaxBayLoad(data);

  return (
    <div className="space-y-5 pb-8">
      {/* Header Actions */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex justify-between items-center no-print text-sans">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-blue-200 shadow-md">
            <ClipboardList size={20} />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-800 leading-tight">Parametry Tabliczki</h2>
            <p className="text-[10px] text-slate-500 font-medium">Edytujesz: <span className="text-blue-600">Project {data.projectNumber}</span></p>
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={onDuplicate} 
            className="flex items-center gap-1.5 text-[10px] font-bold bg-slate-100 text-slate-700 px-3 py-1.5 rounded-lg hover:bg-slate-200 transition-all border border-slate-200"
          >
            Duplikuj
          </button>
          <button 
            onClick={onRemove} 
            className="flex items-center gap-1.5 text-[10px] font-bold bg-red-50 text-red-600 px-3 py-1.5 rounded-lg hover:bg-red-100 transition-all border border-red-100"
          >
            <Trash2 size={12} /> Usuń
          </button>
        </div>
      </div>

      {/* Main Settings Section */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden no-print">
        <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex items-center gap-2">
          <Hash size={16} className="text-slate-400" />
          <h3 className="text-[11px] font-bold text-slate-700 uppercase tracking-wider">Dane Podstawowe</h3>
        </div>
        <div className="p-4 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="md:col-span-2">
            <label className="label">Klient / Nazwa Instalacji</label>
            <input 
              type="text"
              value={data.customerName}
              onChange={(e) => updateField('customerName', e.target.value)}
              className="input-field w-full"
              placeholder="Wpisz nazwę klienta..."
            />
          </div>
          <div>
            <label className="label">Ilość Tabliczek</label>
            <input 
              type="number" 
              min="1"
              value={data.quantity}
              onChange={(e) => updateField('quantity', parseInt(e.target.value) || 1)}
              className="input-field w-full font-bold text-blue-600"
            />
          </div>
          <div>
            <label className="label">Rok Instalacji</label>
            <input 
              type="number"
              value={data.installationYear}
              onChange={(e) => updateField('installationYear', parseInt(e.target.value))}
              className="input-field w-full"
            />
          </div>
          <div>
            <label className="label">Nr Projektu</label>
            <input 
              type="number"
              value={data.projectNumber}
              onChange={(e) => updateField('projectNumber', parseInt(e.target.value))}
              className="input-field w-full"
            />
          </div>
          <div>
            <label className="label">Numer SAP</label>
            <div className="relative group flex items-center">
              <span className="absolute left-3 text-[12px] font-mono text-slate-400 select-none pointer-events-none font-bold">46120</span>
              <input 
                type="text"
                maxLength={5}
                value={data.sapNumberSuffix}
                onChange={(e) => updateField('sapNumberSuffix', e.target.value)}
                className="input-field w-full tracking-widest font-bold text-right pr-3"
                placeholder="XXXXX"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Levels Configuration */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-5 no-print">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-blue-50 px-4 py-2 border-b border-blue-100 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Ruler size={16} className="text-blue-500" />
              <h3 className="text-[11px] font-bold text-blue-900 uppercase tracking-wider">Poziomy - Konf. 1</h3>
            </div>
            <span className="text-[9px] font-black text-blue-400 bg-blue-100/50 px-2 py-0.5 rounded">DOMYŚLNA</span>
          </div>
          <div className="p-4 space-y-4">
            <div>
              <label className="label">Wysokość 1. poziomu (A)</label>
              <div className="relative">
                <input 
                  type="number"
                  value={data.firstLevelHeight}
                  onChange={(e) => updateField('firstLevelHeight', parseInt(e.target.value))}
                  className="input-field w-full pr-10"
                />
                <span className="absolute right-3 top-2 text-[10px] text-slate-400 font-bold">mm</span>
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <label className="label mb-0">Kolejne poziomy</label>
                <button onClick={addLevel} className="text-[9px] font-bold text-blue-600 flex items-center gap-1 hover:underline">
                  <Plus size={10} /> DODAJ ZAKRES
                </button>
              </div>
              <div className="space-y-1.5">
                {data.subsequentLevels.map((lvl) => (
                  <div key={lvl.id} className="flex gap-2 items-center animate-in slide-in-from-right-2 duration-200">
                    <input 
                      type="text"
                      value={lvl.label}
                      onChange={(e) => updateLevel(lvl.id, 'label', e.target.value)}
                      className="input-field w-1/2 text-[11px] font-bold py-1.5"
                      placeholder="Zakres (np. A1-A4)"
                    />
                    <div className="relative w-1/2">
                      <input 
                        type="number"
                        value={lvl.height}
                        onChange={(e) => updateLevel(lvl.id, 'height', parseInt(e.target.value))}
                        className="input-field w-full pr-10 text-[11px] py-1.5"
                      />
                      <span className="absolute right-3 top-2 text-[9px] text-slate-400 font-bold">mm</span>
                    </div>
                    <button onClick={() => removeLevel(lvl.id)} className="text-slate-300 hover:text-red-500 transition-colors p-1">
                      <Trash2 size={14} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden opacity-90 hover:opacity-100 transition-opacity">
          <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Ruler size={16} className="text-slate-400" />
              <h3 className="text-[11px] font-bold text-slate-700 uppercase tracking-wider">Poziomy - Konf. 2</h3>
            </div>
            <span className="text-[9px] font-bold text-slate-400">OPCJONALNA</span>
          </div>
          <div className="p-4 space-y-4">
            <div>
              <label className="label">Wysokość 1. poziomu (A)</label>
              <div className="relative">
                <input 
                  type="number"
                  value={data.firstLevelHeight2 || ''}
                  onChange={(e) => updateField('firstLevelHeight2', e.target.value ? parseInt(e.target.value) : undefined)}
                  className="input-field w-full pr-10"
                  placeholder="Nie ustawiono"
                />
                <span className="absolute right-3 top-2 text-[10px] text-slate-400 font-bold">mm</span>
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <label className="label mb-0">Kolejne poziomy</label>
                <button onClick={addLevel2} className="text-[9px] font-bold text-blue-600 flex items-center gap-1 hover:underline">
                  <Plus size={10} /> DODAJ ZAKRES
                </button>
              </div>
              <div className="space-y-1.5">
                {(data.subsequentLevels2 || []).map((lvl) => (
                  <div key={lvl.id} className="flex gap-2 items-center animate-in slide-in-from-right-2 duration-200">
                    <input 
                      type="text"
                      value={lvl.label}
                      onChange={(e) => updateLevel2(lvl.id, 'label', e.target.value)}
                      className="input-field w-1/2 text-[11px] font-bold py-1.5"
                      placeholder="Zakres"
                    />
                    <div className="relative w-1/2">
                      <input 
                        type="number"
                        value={lvl.height}
                        onChange={(e) => updateLevel2(lvl.id, 'height', parseInt(e.target.value))}
                        className="input-field w-full pr-10 text-[11px] py-1.5"
                      />
                      <span className="absolute right-3 top-2 text-[9px] text-slate-400 font-bold">mm</span>
                    </div>
                    <button onClick={() => removeLevel2(lvl.id)} className="text-slate-300 hover:text-red-500 transition-colors p-1">
                      <Trash2 size={14} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
