import React, { useState, useEffect, useRef, useCallback } from 'react';
import { PlateEditor } from './components/PlateEditor';
import { PlatePreview } from './components/PlatePreview';
import { GlobalEditorModal } from './components/GlobalEditorModal';
import { PlateData, INITIAL_PLATE } from './types';
import { Printer, Plus, FileText, Layout, Layers, Sheet, Download, Upload, FileDown, Settings2, Undo2, Menu, Eye, Edit3, GripVertical, ListOrdered } from 'lucide-react';
import { createDocxBlob } from './utils';

const STORAGE_KEY = 'plateGeneratorData';
const LABELS_PER_PAGE_KEY = 'labelsPerPage';
const MAX_UNDO_STEPS = 50;

const App: React.FC = () => {
  const [plates, setPlates] = useState<PlateData[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : [{ ...INITIAL_PLATE }];
    } catch (e) {
      console.error("Failed to load persistence", e);
      return [{ ...INITIAL_PLATE }];
    }
  });

  const [labelsPerPage, setLabelsPerPage] = useState<number>(() => {
    const saved = localStorage.getItem(LABELS_PER_PAGE_KEY);
    return saved ? parseInt(saved) : 3;
  });

  const [activePlateId, setActivePlateId] = useState<string>(plates[0].id);
  const [viewMode, setViewMode] = useState<'single' | 'sheet'>('single');
  const [mobileTab, setMobileTab] = useState<'editor' | 'preview'>('preview'); 
  const [isGlobalEditorOpen, setIsGlobalEditorOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [leftPanelWidth, setLeftPanelWidth] = useState(60); 
  const [isResizing, setIsResizing] = useState(false);
  const [previewScale, setPreviewScale] = useState(1);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  const [undoStack, setUndoStack] = useState<PlateData[][]>([]);
  const lastSavedStateRef = useRef<PlateData[]>(plates);
  const saveTimeoutRef = useRef<number | null>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    setIsResizing(true);
    e.preventDefault();
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = (e.clientX / window.innerWidth) * 100;
      if (newWidth > 20 && newWidth < 80) {
        setLeftPanelWidth(newWidth);
      }
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const updateScale = () => {
      if (previewContainerRef.current) {
        const containerWidth = previewContainerRef.current.offsetWidth - 40; 
        const plateWidthPx = 190 * 3.78; 
        const newScale = Math.min(containerWidth / plateWidthPx, 1.2);
        setPreviewScale(newScale);
      }
    };

    const observer = new ResizeObserver(updateScale);
    if (previewContainerRef.current) observer.observe(previewContainerRef.current);
    updateScale();

    return () => observer.disconnect();
  }, [leftPanelWidth, viewMode]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(plates));
  }, [plates]);

  useEffect(() => {
    localStorage.setItem(LABELS_PER_PAGE_KEY, labelsPerPage.toString());
  }, [labelsPerPage]);

  const performUndo = useCallback(() => {
    if (undoStack.length === 0) return;
    const previousState = undoStack[undoStack.length - 1];
    const newStack = undoStack.slice(0, -1);
    setUndoStack(newStack);
    lastSavedStateRef.current = previousState;
    setPlates(previousState);
  }, [undoStack]);

  const updatePlatesWithHistory = (newPlates: PlateData[], immediate = false) => {
    const currentState = lastSavedStateRef.current;
    const saveToStack = () => {
      setUndoStack(prev => {
        const next = [...prev, currentState];
        if (next.length > MAX_UNDO_STEPS) return next.slice(1);
        return next;
      });
      lastSavedStateRef.current = newPlates;
    };

    if (immediate) {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveToStack();
    } else {
      if (saveTimeoutRef.current) window.clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = window.setTimeout(saveToStack, 500);
    }
    setPlates(newPlates);
  };

  useEffect(() => {
    if (!plates.find(p => p.id === activePlateId)) {
      setActivePlateId(plates[0]?.id || '');
    }
  }, [plates, activePlateId]);

  const activePlate = plates.find(p => p.id === activePlateId) || plates[0];

  const updateActivePlate = (newData: PlateData) => {
    const newPlates = plates.map(p => p.id === newData.id ? newData : p);
    updatePlatesWithHistory(newPlates);
  };

  const applyGlobalUpdates = (updates: Partial<PlateData>) => {
    const newPlates = plates.map(p => ({ ...p, ...updates }));
    updatePlatesWithHistory(newPlates, true);
  };

  const addNewPlateConfig = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate: PlateData = { ...INITIAL_PLATE, id: newId, quantity: 3 };
    const newPlates = [...plates, newPlate];
    updatePlatesWithHistory(newPlates, true);
    setActivePlateId(newId);
  };

  const duplicatePlate = (plate: PlateData) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newPlate = { ...plate, id: newId };
    const newPlates = [...plates, newPlate];
    updatePlatesWithHistory(newPlates, true);
    setActivePlateId(newId);
  };

  const removePlate = (id: string) => {
    if (plates.length === 1) return;
    const newPlates = plates.filter(p => p.id !== id);
    updatePlatesWithHistory(newPlates, true);
  };

  const handlePrint = () => window.print();

  const handleExport = () => {
    const dataStr = JSON.stringify(plates, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projekty-tabliczki-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleWordExport = async () => {
    const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));
    try {
      const blob = await createDocxBlob(printQueue);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `tabliczki-${new Date().toISOString().split('T')[0]}.docx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Failed to generate DOCX", error);
      alert("Błąd podczas generowania pliku Word.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.length > 0 && json[0].id) {
          updatePlatesWithHistory(json, true);
          setActivePlateId(json[0].id);
        } else {
          alert("Nieprawidłowy format pliku JSON.");
        }
      } catch (err) {
        alert("Błąd podczas odczytu pliku.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const printQueue: PlateData[] = plates.flatMap(p => Array(p.quantity).fill(p));
  const pages: PlateData[][] = [];
  for (let i = 0; i < printQueue.length; i += labelsPerPage) {
    pages.push(printQueue.slice(i, i + labelsPerPage));
  }

  return (
    <div className={`h-screen flex flex-col overflow-hidden bg-gray-50 ${isResizing ? 'cursor-col-resize select-none' : ''}`}>
      <header className="bg-slate-900 text-white p-2 md:p-3 shadow-lg no-print z-30 shrink-0">
        <div className="w-full px-2 md:px-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-800 rounded-lg lg:2xl:hidden block"
              title="Menu projektów"
            >
              <Menu size={20} />
            </button>
            <Layout className="w-6 h-6 text-blue-400 hidden sm:block" />
            <h1 className="text-lg md:text-xl font-bold truncate">Generator Tabliczek</h1>
          </div>

          <div className="flex items-center gap-1 md:gap-2">
             <div className="flex items-center gap-1 mr-1 md:mr-2 border-r border-slate-700 pr-2 md:pr-3">
               <button 
                  onClick={performUndo}
                  disabled={undoStack.length === 0}
                  className={`p-2 rounded transition-colors ${undoStack.length === 0 ? 'text-gray-600 cursor-not-allowed' : 'text-orange-400 hover:bg-slate-800 hover:text-white'}`}
                  title="Cofnij (Ctrl+Z)"
               >
                  <Undo2 size={18} />
               </button>
               <button onClick={() => setIsGlobalEditorOpen(true)} className="p-2 rounded text-yellow-400 hover:bg-slate-800 hover:text-white transition-colors" title="Edycja masowa">
                  <Settings2 size={18} />
               </button>
               <button onClick={handleWordExport} className="p-2 rounded text-blue-300 hover:bg-slate-800 hover:text-white transition-colors hidden sm:block" title="Eksportuj do Word">
                  <FileDown size={18} />
               </button>
               <button onClick={handleImportClick} className="p-2 rounded text-emerald-400 hover:bg-slate-800 hover:text-white transition-colors" title="Wczytaj projekt">
                  <Upload size={18} />
               </button>
               <button onClick={handleExport} className="p-2 rounded text-gray-400 hover:bg-slate-800 hover:text-white transition-colors hidden sm:block" title="Zapisz projekt">
                  <Download size={18} />
               </button>
               <input type="file" accept=".json" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
             </div>
             <button onClick={handlePrint} className="bg-blue-600 hover:bg-blue-500 text-white px-3 md:px-4 py-2 rounded font-semibold flex items-center gap-2 transition-colors text-sm shadow-lg whitespace-nowrap">
              <Printer size={18} />
              <span className="hidden sm:inline">Drukuj</span> <span className="text-[10px] opacity-80">({printQueue.length})</span>
             </button>
          </div>
        </div>
      </header>

      <div className="lg:hidden flex bg-white border-b no-print z-20 shadow-sm shrink-0">
        <button 
          onClick={() => setMobileTab('preview')}
          className={`flex-1 py-3 flex items-center justify-center gap-2 text-sm font-bold border-b-2 transition-colors ${mobileTab === 'preview' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-gray-500'}`}
        >
          <Eye size={16} /> Podgląd
        </button>
        <button 
          onClick={() => setMobileTab('editor')}
          className={`flex-1 py-3 flex items-center justify-center gap-2 text-sm font-bold border-b-2 transition-colors ${mobileTab === 'editor' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-gray-500'}`}
        >
          <Edit3 size={16} /> Edycja
        </button>
      </div>

      <main className="flex-1 flex overflow-hidden w-full relative">
        <aside className={`
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full 2xl:translate-x-0'}
          fixed 2xl:static top-0 left-0 h-full z-40 2xl:z-0
          w-72 bg-white border-r border-gray-200 overflow-y-auto no-print flex flex-col shrink-0 transition-transform duration-300 ease-in-out shadow-2xl 2xl:shadow-none
        `}>
          <div className="p-4 border-b bg-gray-50 flex justify-between items-center sticky top-0 z-10">
             <span className="font-bold text-gray-700 text-sm">Twoje Projekty</span>
             <div className="flex gap-1">
                <button onClick={addNewPlateConfig} className="bg-green-600 text-white p-1.5 rounded hover:bg-green-700 shadow-sm" title="Nowy projekt">
                  <Plus size={16} />
                </button>
                <button onClick={() => setIsSidebarOpen(false)} className="p-1.5 text-gray-400 hover:text-gray-600 2xl:hidden">
                   <Menu size={16} />
                </button>
             </div>
          </div>
          <div className="flex-1 p-2 space-y-2">
            {plates.map((plate, index) => (
              <div 
                key={plate.id}
                onClick={() => {
                  setActivePlateId(plate.id);
                  if (window.innerWidth < 1536) setIsSidebarOpen(false);
                }}
                className={`p-3 rounded-xl cursor-pointer border transition-all ${activePlateId === plate.id ? 'border-blue-500 bg-blue-50 shadow-md ring-2 ring-blue-100' : 'border-gray-200 hover:border-blue-300 hover:bg-gray-50'}`}
              >
                <div className="flex justify-between items-start mb-1">
                  <div className="font-bold text-gray-800 text-xs">Konfiguracja #{index + 1}</div>
                  <div className="bg-white border text-blue-600 text-[10px] px-2 py-0.5 rounded-full font-bold shadow-sm">{plate.quantity} szt.</div>
                </div>
                <div className="text-[11px] text-gray-500 truncate font-mono">Projekt: {plate.projectNumber}</div>
                <div className="text-[11px] text-gray-600 truncate mt-1 font-semibold">{plate.customerName || 'Brak nazwy'}</div>
              </div>
            ))}
          </div>
        </aside>

        {isSidebarOpen && <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-30 2xl:hidden" onClick={() => setIsSidebarOpen(false)} />}

        <div className="flex-1 flex overflow-hidden no-print">
          <section 
            ref={previewContainerRef}
            className={`
              ${mobileTab === 'preview' ? 'flex' : 'hidden lg:flex'}
              bg-gray-200/50 flex flex-col border-r border-gray-200 overflow-hidden
            `}
            style={{ width: window.innerWidth >= 1024 ? `${leftPanelWidth}%` : '100%' }}
          >
            <div className="p-3 flex justify-between items-center bg-white border-b shadow-sm shrink-0">
              <div className="flex items-center gap-2">
                 <h3 className="text-gray-700 font-bold flex items-center gap-2 text-xs uppercase tracking-wider">
                  <FileText size={16} className="text-blue-500" /> Podgląd wydruku
                </h3>
              </div>
              <div className="flex items-center gap-4">
                {viewMode === 'sheet' && (
                  <div className="flex items-center gap-2 border-r border-gray-200 pr-4">
                    <span className="text-[10px] font-black text-gray-400 uppercase flex items-center gap-1">
                      <ListOrdered size={12} /> Etykiet / stronę:
                    </span>
                    <div className="flex bg-gray-100 rounded-lg p-0.5">
                      {[2, 3, 4].map((num) => (
                        <button
                          key={num}
                          onClick={() => setLabelsPerPage(num)}
                          className={`w-7 h-7 flex items-center justify-center rounded-md text-[11px] font-black transition-all ${labelsPerPage === num ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                          {num}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
                <div className="flex bg-gray-100 rounded-lg p-1">
                   <button 
                    onClick={() => setViewMode('single')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'single' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Layers size={14} /> Pojedyncza
                   </button>
                   <button 
                    onClick={() => setViewMode('sheet')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'sheet' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                   >
                     <Sheet size={14} /> Arkusze A4
                   </button>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-auto p-4 md:p-6 flex justify-center items-start bg-slate-200/30">
               {viewMode === 'single' ? (
                  <div 
                    className="bg-white shadow-2xl origin-top p-0 rounded-sm transition-transform duration-200"
                    style={{ transform: `scale(${previewScale})` }}
                  >
                     {activePlate && <PlatePreview data={activePlate} />}
                  </div>
                ) : (
                  <div 
                    className="flex flex-col gap-8 origin-top transition-transform duration-200"
                    style={{ transform: `scale(${previewScale * 0.7})` }}
                  >
                    {pages.map((pagePlates, pageIdx) => (
                      <div 
                        key={pageIdx} 
                        className="bg-white shadow-2xl relative flex flex-col items-center"
                        style={{ width: '210mm', height: '297mm', padding: '10mm' }}
                      >
                         <div className="absolute top-4 left-4 text-gray-200 font-black text-6xl select-none pointer-events-none">A4 - {pageIdx + 1}</div>
                         <div className={`flex flex-col justify-around h-full w-full`}>
                            {pagePlates.map((plate, idx) => (
                              <div key={`${plate.id}-${idx}`} className="flex justify-center">
                                <PlatePreview data={plate} />
                              </div>
                            ))}
                         </div>
                      </div>
                    ))}
                    {pages.length === 0 && <div className="text-gray-500 bg-white p-8 rounded-xl shadow border">Brak elementów do wydruku.</div>}
                  </div>
                )}
            </div>
            <div className="p-2 text-center text-[10px] text-gray-400 border-t bg-white italic">
              {viewMode === 'single' ? `Skala: ${Math.round(previewScale * 100)}%` : `Arkusz: ${pages.length} str.`}
            </div>
          </section>

          <div 
            onMouseDown={startResizing}
            className="hidden lg:flex w-1 bg-gray-300 hover:bg-blue-400 cursor-col-resize items-center justify-center group transition-colors no-print"
          >
            <div className="w-4 h-12 bg-gray-200 border rounded-full flex items-center justify-center group-hover:bg-blue-100 group-hover:border-blue-300 shadow-sm">
               <GripVertical size={14} className="text-gray-400 group-hover:text-blue-500" />
            </div>
          </div>

          <section className={`
            ${mobileTab === 'editor' ? 'flex' : 'hidden lg:flex'}
            flex-1 bg-gray-100 p-3 md:p-6 lg:p-8 overflow-y-auto
          `}>
            <div className="max-w-3xl mx-auto w-full">
              {activePlate && (
                <PlateEditor 
                  data={activePlate} 
                  onChange={updateActivePlate}
                  onDuplicate={() => duplicatePlate(activePlate)}
                  onRemove={() => removePlate(activePlate.id)}
                />
              )}
            </div>
          </section>
        </div>

        <div className="hidden print:block w-full overflow-visible bg-white">
           {pages.map((pagePlates, pageIdx) => (
             <div key={pageIdx} className={`w-full flex flex-col justify-around bg-white ${pageIdx < pages.length - 1 ? 'page-break' : ''}`} style={{ height: '297mm', padding: '10mm 0' }}>
                {pagePlates.map((plate, plateIdx) => (
                  <div key={`${plate.id}-${pageIdx}-${plateIdx}`} className="w-full flex justify-center">
                    <PlatePreview data={plate} />
                  </div>
                ))}
             </div>
           ))}
        </div>
      </main>

      <GlobalEditorModal 
        isOpen={isGlobalEditorOpen}
        onClose={() => setIsGlobalEditorOpen(false)}
        currentTemplate={activePlate}
        onApply={applyGlobalUpdates}
      />
    </div>
  );
};

export default App;
